static NScript::CGameflowScript* g_script;
static SState CurrentState()
{
    SState s;
    s.Value[0] = g_script->MasterScriptData->PostSavePosition;
    s.Value[1] = (long)g_script->CoreQuestWaiting;
    s.Value[2] = g_script->MasterScriptData->BreakSiegeFinished;
    s.Value[3] = g_script->MasterScriptData->BodyGuardsInLimbo;
    return s;
}
static long CurrentStage() { return g_script->MasterScriptData->PostSavePosition; }
void CGameScriptInterface::NewScriptFrame()
{
    Record("NewScriptFrame()");
    ++g_frames;
    if (CurrentStage() == EGP_FINISHED_GAME) ++g_framesAfterGame;
}
// The model's thread: asked to terminate at the g_stopT-th check, or after g_framesToRunAfterGame frames of the finished game.
bool NScript::CGameflowScript::IsActiveThreadTerminating()
{
    Record("T");
    ++g_tCalls;
    if ((g_stopT && g_tCalls >= g_stopT) || (CurrentStage() == EGP_FINISHED_GAME && g_framesAfterGame >= g_framesToRunAfterGame)) g_stopped = true;
    return g_stopped;
}
