static void RunCutsceneMacro(const CCharString& name, CCastMap& cast, const void* flags, const void* strings, bool a, bool b)
{
    char keys[256];
    keys[0] = 0;
    for (int i = 0; i < cast.Count; ++i) {
        if (i) strcat(keys, "+");
        strcat(keys, cast.Keys[i].c_str());
        if (!cast.Values[i].IsValid()) strcat(keys, "(not scripted)");
    }
    Begin("RunCutsceneMacro"); Arg(name); Arg(keys); Arg(flags ? 1 : 0); Arg(strings ? 1 : 0); Arg(a); Arg(b); Tell();
}

